      "pagina_local": "oab-rj-cobra-da-policia-civil-categoria-exclusiva-de-b-o-contra-o-golp.html",
      "link_oficial": "https://agenciabrasil.ebc.com.br/geral/noticia/2026-11/oab-rj-tem-mais-de-3-mil-denuncias-sobre-golpe-do-falso-advogado",
